SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_1253
WHERE it2.id = non_leaf_1253.pi_info_type_id AND (rt.role IN ('actor','actress','cinematographer','costume designer','guest','miscellaneous crew','producer','writer')) AND (t.production_year >= 1990) AND (kt.kind IN ('episode','movie','tv mini series','tv movie','video game','video movie')) AND it1.id = non_leaf_1253.mi1_info_type_id AND mc.movie_id = t.id AND non_leaf_1253.mi1_movie_id = t.id AND kt.id = t.kind_id AND mc.movie_id = non_leaf_1253.ci_movie_id AND cn.id = mc.company_id AND non_leaf_1253.ci_movie_id = t.id AND (it2.id IN ('39')) AND (it1.id IN ('6')) AND (t.production_year <= 2015) AND (pi.info ILIKE '%usa%') AND ct.id = mc.company_type_id AND (mi1.info ILIKE '%dt%');